#include "tracker.hpp"
#include <cerrno>
#include <fcntl.h>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <string_view>
#include <sys/stat.h>
#include <unistd.h>
namespace i2p=biglybtc::services::i2p;namespace cp=i2p::i2cp;
void require(bool ok,const char* why){if(!ok){throw std::runtime_error(why);}}
template<class T,class E>T take(std::expected<T,E> v){if(!v){throw std::runtime_error(v.error().message);}return std::move(*v);}
struct Fd {int n;explicit Fd(int value):n(value){}~Fd(){if(n>=0){::close(n);}}};
bool stamp(const struct stat& a,const struct stat& b){return a.st_dev==b.st_dev&&a.st_ino==b.st_ino&&a.st_size==b.st_size&&a.st_mode==b.st_mode&&a.st_uid==b.st_uid&&a.st_nlink==b.st_nlink&&a.st_mtim.tv_sec==b.st_mtim.tv_sec&&a.st_mtim.tv_nsec==b.st_mtim.tv_nsec&&a.st_ctim.tv_sec==b.st_ctim.tv_sec&&a.st_ctim.tv_nsec==b.st_ctim.tv_nsec;}
i2p::Bytes read(int root,const std::string& leaf){Fd fd(::openat(root,leaf.c_str(),O_RDONLY|O_NOFOLLOW|O_NONBLOCK|O_CLOEXEC));struct stat before{},after{},named{};require(fd.n>=0&&::fstat(fd.n,&before)==0&&S_ISREG(before.st_mode)&&before.st_uid==::geteuid()&&before.st_nlink==1&&before.st_size>=0&&before.st_size<=70000,"Unsafe/unbounded vector");i2p::Bytes out(static_cast<std::size_t>(before.st_size));std::size_t at=0;while(at<out.size()){auto n=::read(fd.n,out.data()+at,out.size()-at);if(n<0&&errno==EINTR){continue;}require(n>0,"Cannot read vector");at+=static_cast<std::size_t>(n);}require(::fstat(fd.n,&after)==0&&::fstatat(root,leaf.c_str(),&named,AT_SYMLINK_NOFOLLOW)==0&&stamp(before,after)&&stamp(after,named),"Vector changed");return out;}
void write(int root,const std::string& leaf,i2p::View bytes){Fd fd(::openat(root,leaf.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW|O_CLOEXEC,0600));require(fd.n>=0&&bytes.size()<=70000,"Cannot exclusively create bounded vector");std::size_t at=0;while(at<bytes.size()){auto n=::write(fd.n,bytes.data()+at,bytes.size()-at);if(n<0&&errno==EINTR){continue;}require(n>0,"Cannot write vector");at+=static_cast<std::size_t>(n);}require(::fsync(fd.n)==0,"Cannot sync vector");}
namespace wire=biglybtc::core::udp_tracker_wire;
i2p::Bytes rawReply(std::uint32_t transaction){const auto put=[](i2p::Bytes& out,std::uint32_t value){for(unsigned i=4;i>0;--i){out.push_back(static_cast<i2p::Byte>(value>>(8*(i-1))));}};i2p::Bytes body;for(const auto n:{2U,transaction,3U,4U,5U}){put(body,n);}auto gzip=take(cp::encodeMuxDatagram({20,6969,9000,std::move(body)},cp::GzipMode::Deflate));gzip.at(9)=18;return gzip;}
void controls(){
  cp::HostLookup lookup{7,0x80000000U,30000,{}};lookup.hash.fill(0x51);auto bytes=take(cp::encodeHostLookup(lookup));auto decoded=take(cp::decodeHostLookup(take(cp::decodeFrame(bytes))));require(decoded.sessionId==7&&decoded.request==lookup.request&&decoded.timeoutMilliseconds==30000&&decoded.hash==lookup.hash,"Lookup hash/unsigned ID differs");require(bytes.size()==48&&bytes.at(15)==0,"LOOKUP_HASH layout differs");auto wrong=bytes;wrong.at(15)=1;require(!cp::decodeHostLookup(take(cp::decodeFrame(wrong))),"Host lookup type accepted");require(!cp::encodeHostLookup({65535,1,30000,{}})&&!cp::encodeHostLookup({7,1,0,{}}),"Unknown session/zero lookup budget accepted");auto failure=take(cp::encodeHostReply({7,0xffffffffU,6,std::nullopt}));auto reply=take(cp::decodeHostReply(take(cp::decodeFrame(failure))));require(reply.sessionId==7&&reply.request==0xffffffffU&&reply.result==6&&!reply.destination,"Exact failure reply differs");auto badFrame=take(cp::decodeFrame(failure));badFrame.payload.push_back(0);require(!cp::decodeHostReply(badFrame),"Trailing failure bytes accepted");auto raw=rawReply(123);require(!cp::decodeMuxDatagram(raw),"General datagram codec acquired raw authority");auto mux=take(cp::decodeRawTrackerReply(raw));require(mux.protocol==18&&mux.fromPort==6969&&mux.toPort==9000,"Raw tracker ports differ");auto result=wire::reply({reinterpret_cast<const char*>(mux.datagram.data()),mux.datagram.size()},123,false);require(result&&result->kind==wire::ReplyKind::Scrape&&result->seeds==3&&result->downloaded==4&&result->peers==5,"Reused BEP15 counts differ");require(!wire::reply({reinterpret_cast<const char*>(mux.datagram.data()),mux.datagram.size()},124,false),"Wrong transaction accepted");raw.at(raw.size()-8)^=1;require(!cp::decodeRawTrackerReply(raw),"Raw gzip CRC error accepted");auto oversized=take(cp::encodeMuxDatagram({20,6969,9000,i2p::Bytes(1025,0x51)},cp::GzipMode::Deflate));oversized.at(9)=18;require(!cp::decodeRawTrackerReply(oversized),"Raw decoded tracker budget exceeded");
}
void interop(const std::filesystem::path& path){
  require(path.is_absolute(),"Absolute root required");Fd root(::open(path.c_str(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC));struct stat st{};require(root.n>=0&&::fstat(root.n,&st)==0&&st.st_uid==::geteuid()&&(st.st_mode&077)==0,"Private owned root required");
  for(const std::string family:{"dsa","ed25519"}){
    auto sender=take(i2p::decodeDestination(read(root.n,family+".sender"))),recipient=take(i2p::decodeDestination(read(root.n,family+".recipient")));auto key=read(root.n,family+".known-test-key");const auto q=take(cp::decodeHostLookup(take(cp::decodeFrame(read(root.n,family+".java.lookup")))));require(q.sessionId==7&&q.request==0x80000000U&&q.timeoutMilliseconds==30000&&q.hash==recipient.hash,"Java lookup differs");auto reply=take(cp::decodeHostReply(take(cp::decodeFrame(read(root.n,family+".java.reply")))));require(reply.sessionId==7&&reply.request==q.request&&!reply.result&&reply.destination&&reply.destination->wire==recipient.wire,"Java full lookup reply differs");const auto encoded=take(cp::encodeHostLookup(q));require(encoded==read(root.n,family+".java.lookup"),"Exact lookup writer differs");write(root.n,family+".native.lookup",encoded);auto encodedReply=take(cp::encodeHostReply(reply));require(encodedReply==read(root.n,family+".java.reply"),"Exact reply writer differs");write(root.n,family+".native.reply",encodedReply);
    for(const bool connecting:{true,false}){const auto label=family+(connecting?".connect":".scrape");const auto send=take(cp::decodeSendDatagram(take(cp::decodeFrame(read(root.n,label+".java")))));require(send.sessionId==7&&send.nonce==0&&send.skipLeaseSet==!connecting&&send.expirationMilliseconds==1700000060123ULL&&send.recipient.wire==recipient.wire,"Original Expires/skipLS fields differ");const auto mux=take(cp::decodeMuxDatagram(send.payload));require(mux.protocol==(connecting?19:20)&&mux.fromPort==9000&&mux.toPort==6969,"Original tracker mux differs");i2p::Bytes payload;if(connecting){auto d=take(i2p::decode2(mux.datagram,recipient.hash));require(d.sender.wire==sender.wire,"Original tracker signer differs");payload=std::move(d.payload);}else{auto d=take(i2p::decode3(mux.datagram));require(d.claimedSender==sender.hash,"Original claimed tracker sender differs");payload=std::move(d.payload);}if(connecting){const auto expected=wire::connect(123);require(payload==i2p::Bytes(expected.begin(),expected.end()),"Original connect differs");}else{std::array<std::byte,20> hash;hash.fill(std::byte{0x51});const auto expected=wire::scrape(0x123456789abcdef0ULL,124,hash);require(payload==i2p::Bytes(expected.begin(),expected.end()),"Original scrape differs");}auto packet=take(connecting?i2p::encode2(sender.wire,key,recipient.hash,payload):i2p::encode3(sender.wire,payload));auto gzip=take(cp::encodeMuxDatagram({connecting?i2p::Datagram2Protocol:i2p::Datagram3Protocol,9000,6969,std::move(packet)},cp::GzipMode::Deflate));write(root.n,label+".native",take(cp::encodeSendDatagram({7,recipient,std::move(gzip),0,1700000060123ULL,!connecting})));}
    const auto inbound=take(cp::decodeMessagePayload(take(cp::decodeFrame(read(root.n,family+".java.raw")))));auto mux=take(cp::decodeRawTrackerReply(inbound.payload));require(inbound.sessionId==7&&inbound.messageId==99&&mux.fromPort==6969&&mux.toPort==9000,"Original raw reply envelope differs");const auto counts=wire::reply({reinterpret_cast<const char*>(mux.datagram.data()),mux.datagram.size()},124,false);require(counts&&counts->kind==wire::ReplyKind::Scrape&&counts->seeds==3&&counts->downloaded==4&&counts->peers==5,"Original raw counts differ");write(root.n,family+".native.raw",take(cp::encodeMessagePayload({7,99,rawReply(124)})));std::cout<<"PASS NATIVE VERIFIED JAVA "<<family<<" tracker objects\n";
  }
  require(::fsync(root.n)==0,"Cannot sync vector directory");
}
int main(int argc,char** argv){try{if(argc==3&&std::string_view(argv[1])=="--java-interop"){interop(argv[2]);return 0;}require(argc==1,"Usage: i2cp-tracker-codec-tests [--java-interop ROOT]");controls();std::cout<<"PASS bounded original tracker lookup/raw codec\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
